package com.hbm.satellite.cargo;
import com.hbm.satellite.item.SatelliteChipItem;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;
public final class SatelliteDockMenu extends AbstractContainerMenu {
 public final SatelliteDockBlockEntity machine;public SatelliteDockMenu(int id,Inventory player,RegistryFriendlyByteBuf buffer){this(id,player,(SatelliteDockBlockEntity)player.player.level().getBlockEntity(buffer.readBlockPos()));}public SatelliteDockMenu(int id,Inventory player,SatelliteDockBlockEntity machine){super(SatelliteCargoContent.MENU.get(),id);this.machine=machine;for(int i=0;i<15;i++)addSlot(new Slot(machine,i,71+i%5*18,18+i/5*18){@Override public boolean mayPlace(ItemStack stack){return false;}});addSlot(new Slot(machine,15,26,36){@Override public boolean mayPlace(ItemStack stack){return stack.getItem() instanceof SatelliteChipItem;}});for(int i=0;i<27;i++)addSlot(new Slot(player,9+i,8+i%9*18,104+i/9*18));for(int i=0;i<9;i++)addSlot(new Slot(player,i,8+i*18,162));}
 @Override public boolean stillValid(Player player){return machine.stillValid(player);}@Override public ItemStack quickMoveStack(Player player,int index){if(index<0||index>=slots.size())return ItemStack.EMPTY;var slot=slots.get(index);if(!slot.hasItem())return ItemStack.EMPTY;var stack=slot.getItem();var original=stack.copy();if(index<=15){if(!moveItemStackTo(stack,16,slots.size(),true))return ItemStack.EMPTY;}else if(!moveItemStackTo(stack,0,15,false))return ItemStack.EMPTY;if(stack.isEmpty())slot.set(ItemStack.EMPTY);else slot.setChanged();return original;}
}
